    {
        switch (summon->GetEntry())
        {
        case npc_evala_guard:
            ++addDied;
            summon->DespawnOrUnsummon(500);
            if (addDied == 7)
            {
                EvalaFlags(false);
                me->RemoveAura(SPELL_EVALA_TRANSFORM);
            }
            break;
